180 | function generateTitanReply(userText: string, profile: Profile): string {
181 |   const t = userText.toLowerCase();
182 |   if (t.includes("pollo") || t.includes("arroz") || t.includes("tomate") || t.includes("tengo")) {
183 |     return "Con eso puedo montarte algo rápido: saltea el pollo en dados, añade el arroz ya cocido y el tomate troceado al final con un chorrito de aceite de oliva y comino. Encaja bien en tus macros de hoy.";
184 |   }
185 |   if (t.includes("cansad") || t.includes("dormido") || t.includes("sueño") || t.includes("mal dormido")) {
186 |     return "Entendido. He suavizado un poco la intensidad del entreno de hoy — bajamos el RPE objetivo de las últimas series. Prioriza dormir esta noche, el plan se adapta contigo.";
187 |   }
188 |   if (t.includes("dolor") || t.includes("molest") || t.includes("lesion")) {
189 |     return "Gracias por avisar. He quitado temporalmente los ejercicios que puedan cargar esa zona y los sustituyo por variantes más seguras hasta que me digas que ha mejorado.";
190 |   }
191 |   if (t.includes("cerveza") || t.includes("alcohol") || t.includes("fin de semana") || t.includes("finde")) {
192 |     return "Disfrutar también forma parte de una vida saludable. Esta semana simplemente volveremos poco a poco a la rutina, sin prisa.";
193 |   }
194 |   if (t.includes("gracias")) {
195 |     return "Para eso estoy. Cualquier cosa, aquí me tienes.";
196 |   }
197 |   return `Anotado${profile.goal ? `, sigo ajustando todo en función de tu objetivo (${profile.goal.toLowerCase()})` : ""}. Cuéntame más si quieres que cambie algo del plan de esta semana.`;
198 | }
