204 |       stepIndex: 0,
205 |       profile: {},
206 |       history: [],
207 |       answerStep: (field, value) =>
208 |         set((state) => ({
209 |           profile: { ...state.profile, [field]: value },
210 |           history: [...state.history, { role: "user", text: value }],
211 |           stepIndex: state.stepIndex + 1,
212 |         })),
213 |       completeOnboarding: () => set({ onboardingCompleted: true }),
214 |       resetOnboarding: () =>
215 |         set({ onboardingCompleted: false, stepIndex: 0, profile: {}, history: [] }),
216 | 
217 |       todayWorkout: {
218 |         title: "Empuje — Fuerza",
219 |         meta: "5 ejercicios · ~52 min · Gimnasio completo",
220 |         exercises: initialExercises,
221 |         completed: false,
222 |       },
223 |       logSet: (exerciseId, newSet) =>
224 |         set((state) => ({
225 |           todayWorkout: {
226 |             ...state.todayWorkout,
227 |             exercises: state.todayWorkout.exercises.map((ex) =>
228 |               ex.id === exerciseId
229 |                 ? { ...ex, loggedSets: [...ex.loggedSets, newSet] }
230 |                 : ex
231 |             ),
232 |           },
233 |         })),
234 |       completeWorkout: () =>
235 |         set((state) => ({
236 |           todayWorkout: { ...state.todayWorkout, completed: true },
237 |           chatMessages: [
238 |             ...state.chatMessages,
239 |             {
240 |               role: "titan",
241 |               text: "Entreno registrado 💪 Con los pesos y RPE de hoy voy a ajustar la carga de la próxima semana.",
242 |             },
243 |           ],
244 |         })),
245 | 
246 |       meals: initialMeals,
247 |       mealsCompleted: {},
248 |       toggleMealDone: (mealId) =>
249 |         set((state) => ({
250 |           mealsCompleted: {
251 |             ...state.mealsCompleted,
252 |             [mealId]: !state.mealsCompleted[mealId],
253 |           },
254 |         })),
255 |       swapMeal: (mealId) =>
256 |         set((state) => ({
257 |           meals: state.meals.map((meal) => {
258 |             if (meal.id !== mealId || meal.alternatives.length === 0) return meal;
259 |             const [nextAlt, ...rest] = meal.alternatives;
260 |             const currentAsAlt: MealMacros = {
261 |               name: meal.name,
262 |               kcal: meal.kcal,
263 |               protein: meal.protein,
264 |               carbs: meal.carbs,
265 |               fat: meal.fat,
266 |             };
267 |             return { ...meal, ...nextAlt, alternatives: [...rest, currentAsAlt] };
268 |           }),
269 |         })),
270 | 
271 |       shoppingList: initialShoppingList,
272 |       toggleShoppingItem: (id) =>
273 |         set((state) => ({
274 |           shoppingList: state.shoppingList.map((item) =>
275 |             item.id === id ? { ...item, checked: !item.checked } : item
276 |           ),
277 |         })),
278 |       resetShoppingList: () =>
279 |         set((state) => ({
280 |           shoppingList: state.shoppingList.map((item) => ({ ...item, checked: false })),
281 |         })),
282 | 
283 |       weighIns: initialWeighIns,
284 |       addWeighIn: (weight) =>
285 |         set((state) => ({
286 |           weighIns: [
287 |             ...state.weighIns,
288 |             { date: `Semana ${state.weighIns.length + 1}`, weight },
289 |           ],
290 |         })),
291 | 
292 |       chatMessages: [
293 |         {
294 |           role: "titan",
295 |           text: "Hola, soy Titan. Cuéntame cómo va tu día, qué tienes en la nevera, o si algo no te está funcionando del plan.",
296 |         },
297 |       ],
298 |       sendChatMessage: (text) =>
299 |         set((state) => ({
300 |           chatMessages: [
