"use client";

import { create } from "zustand";
import { persist } from "zustand/middleware";

/* ─────────────────────────────────────────────
   TIPOS
───────────────────────────────────────────── */

export type ChatTurn = { role: "titan" | "user"; text: string };

export type Profile = {
  // datos personales
  name?: string;
  age?: string;
  sex?: string;
  height?: string;
  weight?: string;
  targetWeight?: string;
  // objetivo
  goal?: string;
  // entrenamiento
  level?: string;
  trainingDays?: string;
  trainingPlace?: string;
  equipment?: string;
  injury?: string;
  // nutrición
  allergies?: string;
  dietPreference?: string;
  // hábitos
  sleepHours?: string;
  dailyActivity?: string;
  supermarket?: string;
};

export type LoggedSet = { weight: number; reps: number; rpe: number };

export type Exercise = {
  id: string;
  name: string;
  targetSets: number;
  targetReps: string;
  muscleGroup?: string;
  loggedSets: LoggedSet[];
};

export type MealMacros = {
  name: string;
  kcal: number;
  protein: number;
  carbs: number;
  fat: number;
};

export type Meal = MealMacros & {
  id: "desayuno" | "comida" | "cena" | "snack";
  icon: string;
  alternatives: MealMacros[];
};

export type ShoppingItem = {
  id: string;
  name: string;
  category: string;
  checked: boolean;
};

export type WeighIn = { date: string; weight: number };

export type ChatMessage = { role: "user" | "titan"; text: string };

export type Achievement = {
  id: string;
  title: string;
  description: string;
  icon: string;
  unlockedAt?: string;
  xpReward: number;
};

export type Challenge = {
  id: string;
  title: string;
  description: string;
  type: "daily" | "weekly" | "monthly";
  progress: number;
  target: number;
  unit: string;
  xpReward: number;
  completed: boolean;
};

export type Friend = {
  id: string;
  name: string;
  level: number;
  xp: number;
  streak: number;
  avatar?: string;
  commitmentIndex: number;
  position: number;
};

export type FeedItem = {
  id: string;
  userId: string;
  userName: string;
  action: string;
  timestamp: string;
  icon: string;
};

export type Duel = {
  id: string;
  opponentId: string;
  opponentName: string;
  type: string;
  myScore: number;
  opponentScore: number;
  status: "active" | "won" | "lost" | "pending";
  startedAt: string;
  endsAt: string;
};

export type DailyStats = {
  date: string;
  water: number;
  steps: number;
  sleepHours: number;
  caloriesBurned: number;
  workoutMinutes: number;
  proteinGrams: number;
};

