      updateWater: (liters) =>
        set((state) => ({ dailyStats: { ...state.dailyStats, water: liters } })),
      updateSteps: (steps) =>
        set((state) => ({ dailyStats: { ...state.dailyStats, steps } })),

      todayWorkout: {
        title: "Empuje — Fuerza",
        meta: "5 ejercicios · ~52 min · Gimnasio completo",
        exercises: initialExercises,
