              ex.id === exerciseId
                ? { ...ex, loggedSets: [...ex.loggedSets, newSet] }
                : ex
            ),
          },
        })),
      completeWorkout: () =>
        set((state) => ({
          todayWorkout: { ...state.todayWorkout, completed: true },
          xp: state.xp + 120,
