@import "tailwindcss";

/* ─────────────────────────────────────────────
   DESIGN TOKENS — DARK (default)
───────────────────────────────────────────── */
:root {
  --color-bg: #000000;
  --color-surface: #0a0a0a;
  --color-surface-2: #111111;
  --color-text: #ffffff;
  --color-text-dim: rgba(255, 255, 255, 0.52);
  --color-text-dimmer: rgba(255, 255, 255, 0.32);
  --color-accent: #c6ff00;
  --color-accent-dim: rgba(198, 255, 0, 0.14);
  --color-accent-rgb: 198, 255, 0;
  --color-glass: rgba(255, 255, 255, 0.055);
  --color-glass-strong: rgba(255, 255, 255, 0.09);
  --color-border: rgba(255, 255, 255, 0.1);
  --color-border-strong: rgba(255, 255, 255, 0.16);

  /* semantic */
  --color-success: #34d399;
  --color-success-dim: rgba(52, 211, 153, 0.15);
  --color-warning: #fbbf24;
  --color-warning-dim: rgba(251, 191, 36, 0.15);
  --color-danger: #f87171;
  --color-danger-dim: rgba(248, 113, 113, 0.15);
  --color-blue: #60a5fa;
  --color-blue-dim: rgba(96, 165, 250, 0.15);
  --color-purple: #a78bfa;
  --color-purple-dim: rgba(167, 139, 250, 0.15);
  --color-orange: #fb923c;
  --color-orange-dim: rgba(251, 146, 60, 0.15);

  --radius-xl: 32px;
  --radius-lg: 28px;
  --radius-md: 20px;
  --radius-sm: 14px;
  --radius-xs: 10px;

  --font-app: -apple-system, "SF Pro Display", "Inter", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

/* ─────────────────────────────────────────────
   TAILWIND THEME EXTENSION
───────────────────────────────────────────── */
@theme inline {
  --color-bg: var(--color-bg);
  --color-surface: var(--color-surface);
  --color-surface-2: var(--color-surface-2);
  --color-text: var(--color-text);
  --color-text-dim: var(--color-text-dim);
  --color-text-dimmer: var(--color-text-dimmer);
  --color-accent: var(--color-accent);
  --color-accent-dim: var(--color-accent-dim);
  --color-glass: var(--color-glass);
  --color-glass-strong: var(--color-glass-strong);
  --color-border: var(--color-border);
  --color-border-strong: var(--color-border-strong);

  --color-success: var(--color-success);
  --color-success-dim: var(--color-success-dim);
  --color-warning: var(--color-warning);
  --color-warning-dim: var(--color-warning-dim);
  --color-danger: var(--color-danger);
  --color-danger-dim: var(--color-danger-dim);
  --color-blue: var(--color-blue);
  --color-blue-dim: var(--color-blue-dim);
  --color-purple: var(--color-purple);
  --color-purple-dim: var(--color-purple-dim);
  --color-orange: var(--color-orange);
  --color-orange-dim: var(--color-orange-dim);

  --radius-xl: var(--radius-xl);
  --radius-lg: var(--radius-lg);
  --radius-md: var(--radius-md);
  --radius-sm: var(--radius-sm);
  --radius-xs: var(--radius-xs);

  --font-sans: var(--font-app);
}

/* ─────────────────────────────────────────────
   BASE
───────────────────────────────────────────── */
* {
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  background: var(--color-bg);
  color: var(--color-text);
  overscroll-behavior-y: none;
}

body {
  font-family: var(--font-app);
}

::-webkit-scrollbar {
  display: none;
}

.tabular-nums {
  font-variant-numeric: tabular-nums;
}

/* ─────────────────────────────────────────────
   RING / CIRCLE PROGRESS (SVG utility)
───────────────────────────────────────────── */
.ring-progress {
  transform-origin: center;
  transform: rotate(-90deg);
}

/* ─────────────────────────────────────────────
   ANIMACIONES
───────────────────────────────────────────── */
@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

@keyframes float-up {
  0% { opacity: 0; transform: translateY(12px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes scale-in {
  0% { opacity: 0; transform: scale(0.88); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(var(--color-accent-rgb), 0.4); }
  50% { box-shadow: 0 0 0 8px rgba(var(--color-accent-rgb), 0); }
}

.skeleton {
  background: linear-gradient(90deg, var(--color-glass) 25%, var(--color-glass-strong) 50%, var(--color-glass) 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
}

.animate-float-up {
  animation: float-up 0.3s ease both;
}

.animate-scale-in {
  animation: scale-in 0.25s ease both;
}

.animate-pulse-glow {
  animation: pulse-glow 2s ease infinite;
}

