"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import { useTitanStore, xpToLevel } from "@/lib/store";
import { TabBar } from "@/components/TabBar";
import { GlassCard } from "@/components/ui/GlassCard";
import { TitanAvatar } from "@/components/ui/TitanAvatar";
import { AchievementToast } from "@/components/ui/AchievementToast";

function RingProgress({ pct, size = 60, stroke = 5, color = "var(--color-accent)" }: {
  pct: number; size?: number; stroke?: number; color?: string;
}) {
  const r = (size - stroke * 2) / 2;
  const circ = 2 * Math.PI * r;
  const offset = circ * (1 - Math.min(pct, 100) / 100);
  return (
    <svg width={size} height={size}>
      <circle cx={size / 2} cy={size / 2} r={r} stroke="rgba(255,255,255,0.08)" strokeWidth={stroke} fill="none" />
      <circle
        cx={size / 2} cy={size / 2} r={r}
        stroke={color} strokeWidth={stroke} fill="none"
        strokeDasharray={circ} strokeDashoffset={offset}
        strokeLinecap="round"
        className="ring-progress transition-all duration-700"
      />
    </svg>
  );
}

const fadeUp = { initial: { opacity: 0, y: 16 }, animate: { opacity: 1, y: 0 } };

export default function HomePage() {
  const router = useRouter();
  const { onboardingCompleted, profile, todayWorkout, dailyStats, xp, streak, userRankPosition, userCommitmentIndex, challenges } = useTitanStore();

  useEffect(() => {
    if (!onboardingCompleted) router.replace("/onboarding");
  }, [onboardingCompleted, router]);

  if (!onboardingCompleted) return null;

  const { level } = xpToLevel(xp);
  const firstName = profile.name?.split(" ")[0] ?? "Campeón";
  const hour = new Date().getHours();
  const greeting = hour < 13 ? "Buenos días" : hour < 20 ? "Buenas tardes" : "Buenas noches";

  const targetKcal = 2200;
  const targetProtein = 160;
  const targetWater = 2.5;
  const targetSteps = 10000;

  const completedMealsKcal = 1720;
  const completedProtein = 123;

  const dailyChallenges = challenges.filter(c => c.type === "daily" && !c.completed).slice(0, 3);

  return (
    <>
      <AchievementToast />
      <div className="flex min-h-dvh flex-col gap-4 px-4 pb-[110px] pt-1">

        {/* Header */}
        <motion.div {...fadeUp} transition={{ duration: 0.35 }} className="px-1 pt-3">
          <div className="flex items-start justify-between">
            <div>
              <div className="text-[13px] font-semibold text-text-dim">{greeting}</div>
              <div className="mt-0.5 text-[28px] font-extrabold tracking-[-0.5px]">{firstName} 👋</div>
            </div>
            <div className="flex flex-col items-end gap-1">
              <div
                onClick={() => router.push("/perfil")}
                className="flex h-10 w-10 cursor-pointer items-center justify-center rounded-full bg-accent font-extrabold text-black text-[14px]"
              >
                {firstName[0]?.toUpperCase()}
              </div>
              <div className="text-[11px] font-bold text-text-dim">Nv. {level}</div>
            </div>
          </div>

          {/* Racha y ranking pills */}
          <div className="mt-3 flex gap-2">
            <div className="flex items-center gap-1.5 rounded-full border border-orange/30 bg-orange-dim px-3 py-1.5">
              <span className="text-[13px]">🔥</span>
              <span className="text-[12px] font-bold text-orange">{streak} días seguidos</span>
            </div>
            <div
              onClick={() => router.push("/ranking")}
              className="flex cursor-pointer items-center gap-1.5 rounded-full border border-accent/30 bg-accent-dim px-3 py-1.5"
            >
              <span className="text-[12px] font-bold text-accent">#{userRankPosition} amigos</span>
            </div>
            <div className="flex items-center gap-1.5 rounded-full border border-purple/30 bg-purple-dim px-3 py-1.5">
              <span className="text-[12px] font-bold text-purple">{userCommitmentIndex}% índice</span>
            </div>
          </div>
        </motion.div>

        {/* Rings de actividad */}
        <motion.div {...fadeUp} transition={{ duration: 0.35, delay: 0.05 }}>
          <GlassCard className="p-4">
            <div className="mb-3 flex items-center justify-between">
              <div className="text-[14px] font-bold">Actividad de hoy</div>
              <div className="text-[11px] text-text-dim">
                {new Date().toLocaleDateString("es-ES", { weekday: "long", day: "numeric", month: "short" })}
              </div>
            </div>
            <div className="flex items-center justify-around">
              {/* Calorías */}
              <div className="flex flex-col items-center gap-1.5">
                <div className="relative">
                  <RingProgress pct={Math.round(completedMealsKcal / targetKcal * 100)} size={68} stroke={6} color="var(--color-orange)" />
                  <div className="absolute inset-0 flex items-center justify-center">
                    <span className="text-[9px] font-bold text-orange">🔥</span>
                  </div>
                </div>
                <div className="text-center">
                  <div className="tabular-nums text-[14px] font-extrabold">{completedMealsKcal}</div>
                  <div className="text-[9.5px] text-text-dim">de {targetKcal} kcal</div>
                </div>
              </div>
              {/* Proteína */}
              <div className="flex flex-col items-center gap-1.5">
                <div className="relative">
                  <RingProgress pct={Math.round(completedProtein / targetProtein * 100)} size={68} stroke={6} color="var(--color-blue)" />
                  <div className="absolute inset-0 flex items-center justify-center">
                    <span className="text-[9px] font-bold text-blue">💪</span>
                  </div>
                </div>
                <div className="text-center">
                  <div className="tabular-nums text-[14px] font-extrabold">{completedProtein}g</div>
                  <div className="text-[9.5px] text-text-dim">de {targetProtein}g prot.</div>
                </div>
              </div>
              {/* Agua */}
              <div className="flex flex-col items-center gap-1.5">
                <div className="relative">
