                  <div className="mt-0.5 text-[10px] font-semibold text-text-dim">
                    {s.label}
                  </div>
                  <div className="mt-2 h-1 overflow-hidden rounded-full bg-white/8">
                    <div
                      className="h-full rounded-full bg-accent"
                      style={{ width: `${s.pct}%` }}
                    />
                  </div>
                </div>
              ))}
