                {
                  icon: "💧",
                  value: `${dailyStats.water}L`,
                  label: `de ${targetWater}L`,
                  pct: Math.round((dailyStats.water / targetWater) * 100),
                },
                {
                  icon: "👣",
                  value: dailyStats.steps.toLocaleString("es"),
                  label: "pasos hoy",
