  const resetOnboarding = useTitanStore((s) => s.resetOnboarding);

  function handleReset() {
    if (confirm("Esto reinicia tu perfil y vuelve a empezar el onboarding. ¿Continuar?")) {
      resetOnboarding();
      router.push("/onboarding");
    }
  }

  if (!ready) return null;

  return (
