import type { Metadata, Viewport } from "next";
import "./globals.css";

export const metadata: Metadata = {
  title: "Titania — Tu entrenador personal",
  description: "Fitness de nivel comercial. Entrena, come bien y compite con tus amigos.",
  manifest: "/manifest.json",
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  maximumScale: 1,
  themeColor: "#000000",
  viewportFit: "cover",
};

export default function RootLayout({
  children,
}: Readonly<{ children: React.ReactNode }>) {
  return (
    <html lang="es">
      <body className="bg-bg text-text antialiased">
        <div className="mx-auto min-h-dvh w-full max-w-[480px] bg-bg">
          {children}
        </div>
      </body>
    </html>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { AnimatePresence, motion } from "framer-motion";
import { useTitanStore } from "@/lib/store";
import { onboardingSteps } from "@/lib/onboardingSteps";
import { TitanAvatar } from "@/components/ui/TitanAvatar";
import { Chip } from "@/components/ui/Chip";

export default function OnboardingPage() {
  const router = useRouter();
  const { stepIndex, history, answerStep, completeOnboarding } = useTitanStore();
  const [freeText, setFreeText] = useState("");
  const bodyRef = useRef<HTMLDivElement>(null);

  const finished = stepIndex >= onboardingSteps.length;
  const currentStep = !finished ? onboardingSteps[stepIndex] : null;

  useEffect(() => {
    bodyRef.current?.scrollTo({ top: bodyRef.current.scrollHeight, behavior: "smooth" });
  }, [stepIndex]);

  useEffect(() => {
    if (finished) {
      const t = setTimeout(() => {
        completeOnboarding();
        router.push("/home");
      }, 1800);
      return () => clearTimeout(t);
    }
  }, [finished, completeOnboarding, router]);

  function handleAnswer(value: string) {
    if (!currentStep) return;
    answerStep(currentStep.field, value);
    setFreeText("");
  }

  const pct = Math.round((stepIndex / onboardingSteps.length) * 100);
  const hasChips = currentStep && currentStep.chips.length > 0;
  const hasFreeText = currentStep && (currentStep.chips.length === 0 || currentStep.freeTextPlaceholder);

  return (
    <div className="flex h-dvh flex-col bg-bg">
      {/* Progress bar */}
      <div className="shrink-0 px-5 pb-3.5 pt-[18px]">
        <div className="flex items-center justify-between mb-1.5">
          <span className="text-[11px] font-bold text-text-dimmer">
            {stepIndex}/{onboardingSteps.length}
          </span>
          <span className="text-[11px] font-bold text-accent">{pct}%</span>
        </div>
        <div className="h-[3px] overflow-hidden rounded-full bg-white/10">
          <motion.div
            className="h-full rounded-full bg-accent"
            initial={{ width: 0 }}
            animate={{ width: `${pct}%` }}
            transition={{ duration: 0.4, ease: "easeOut" }}
          />
        </div>
      </div>

      {/* Conversación */}
      <div
        ref={bodyRef}
        className="flex flex-1 flex-col gap-4 overflow-y-auto px-5 pb-5 pt-2"
      >
        {history.map((turn, i) => {
          if (turn.role === "user") {
            return (
              <motion.div
                key={i}
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                className="max-w-[80%] self-end rounded-[18px] rounded-tr-[4px] bg-accent px-4 py-3 text-[13.5px] font-semibold text-black"
              >
                {turn.text}
              </motion.div>
            );
          }
          return (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              className="flex max-w-[88%] items-start gap-2.5"
            >
              <TitanAvatar size={30} />
              <div className="rounded-[18px] rounded-tl-[4px] border border-border bg-glass-strong px-4 py-[13px] text-[14px] leading-[1.5]">
                {turn.text.split("\n").map((line, j) => (
                  <p key={j} className={j > 0 ? "mt-3" : ""}>{line}</p>
                ))}
              </div>
            </motion.div>
          );
        })}

        {/* Pregunta actual */}
        <AnimatePresence mode="wait">
          {currentStep && (
            <motion.div
              key={stepIndex}
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              className="flex flex-col gap-3"
            >
              <div className="flex max-w-[88%] items-start gap-2.5">
                <TitanAvatar size={30} />
                <div className="rounded-[18px] rounded-tl-[4px] border border-border bg-glass-strong px-4 py-[13px] text-[14px] leading-[1.5]">
                  {currentStep.question.split("\n").map((line, j) => (
                    <p key={j} className={j > 0 ? "mt-3" : ""}>{line}</p>
                  ))}
                </div>
              </div>
              {hasChips && (
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: 0.15 }}
                  className="flex flex-wrap gap-2 pl-[40px]"
                >
                  {currentStep.chips.map((chip) => (
                    <Chip key={chip} label={chip} onClick={() => handleAnswer(chip)} />
                  ))}
                </motion.div>
              )}
            </motion.div>
          )}

          {finished && (
            <motion.div
              key="done"
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              className="flex max-w-[88%] items-start gap-2.5"
            >
              <TitanAvatar size={30} />
              <div className="rounded-[18px] rounded-tl-[4px] border border-border bg-glass-strong px-4 py-[13px] text-[14px] leading-[1.5]">
                Perfecto, ya te conozco lo suficiente para empezar. Estoy
                preparando tu primera semana de entrenamiento y tu lista de la
                compra — dame un segundo 🔧
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Input */}
      {!finished && (
        <form
          className="shrink-0 px-5 pb-[26px] pt-3.5"
          onSubmit={(e) => {
            e.preventDefault();
            if (freeText.trim()) handleAnswer(freeText.trim());
          }}
        >
          <div className="flex items-center gap-2.5 rounded-full border border-border bg-glass py-1.5 pl-[18px] pr-1.5">
            <input
              value={freeText}
              onChange={(e) => setFreeText(e.target.value)}
              placeholder={
                currentStep?.freeTextPlaceholder ?? "Escribe tu respuesta..."
              }
              className="flex-1 bg-transparent py-2 text-[14px] text-text placeholder:text-text-dimmer outline-none"
            />
            <button
              type="submit"
              disabled={!freeText.trim()}
              className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-accent text-[15px] font-extrabold text-black disabled:opacity-40"
            >
              ↑
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useTitanStore } from "@/lib/store";
import { useRequireOnboarding } from "@/lib/useRequireOnboarding";
import { TitanAvatar } from "@/components/ui/TitanAvatar";
import { TabBar } from "@/components/TabBar";

const QUICK_PROMPTS = [
  "¿Cómo voy en el ranking?",
  "¿Qué como hoy?",
  "Estoy cansado",
  "¿Cuánta proteína me falta?",
];

export default function TitanChatPage() {
  const ready = useRequireOnboarding();
  const chatMessages = useTitanStore((s) => s.chatMessages);
  const sendChatMessage = useTitanStore((s) => s.sendChatMessage);
  const profile = useTitanStore((s) => s.profile);
  const [text, setText] = useState("");
  const bodyRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bodyRef.current?.scrollTo({ top: bodyRef.current.scrollHeight, behavior: "smooth" });
  }, [chatMessages]);

  function submit(e: React.FormEvent) {
    e.preventDefault();
    if (!text.trim()) return;
    sendChatMessage(text.trim());
    setText("");
  }

  function sendPrompt(prompt: string) {
    sendChatMessage(prompt);
  }

  if (!ready) return null;

  return (
    <div className="flex h-dvh flex-col">
      {/* Header */}
      <div className="flex shrink-0 items-center gap-3 border-b border-border px-5 pb-3.5 pt-5">
        <TitanAvatar size={38} pulse />
        <div>
          <div className="text-[15px] font-bold">Titan</div>
          <div className="text-[11.5px] text-text-dim">
            Tu entrenador personal · IA
          </div>
        </div>
        <div className="ml-auto flex items-center gap-1.5 rounded-full border border-success/30 bg-success-dim px-3 py-1">
          <div className="h-1.5 w-1.5 rounded-full bg-success" />
          <span className="text-[11px] font-semibold text-success">Activo</span>
        </div>
      </div>

      {/* Mensajes */}
      <div
        ref={bodyRef}
        className="flex flex-1 flex-col gap-3 overflow-y-auto px-5 py-4"
      >
        <AnimatePresence initial={false}>
          {chatMessages.map((m, i) =>
            m.role === "user" ? (
              <motion.div
                key={i}
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                className="max-w-[80%] self-end rounded-[18px] rounded-tr-[4px] bg-accent px-4 py-3 text-[13.5px] font-semibold text-black"
              >
                {m.text}
              </motion.div>
            ) : (
              <motion.div
                key={i}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                className="flex max-w-[88%] items-start gap-2.5"
              >
                <TitanAvatar size={28} />
                <div className="rounded-[18px] rounded-tl-[4px] border border-border bg-glass-strong px-4 py-[13px] text-[14px] leading-[1.5]">
                  {m.text}
                </div>
              </motion.div>
            )
          )}
        </AnimatePresence>
      </div>

      {/* Quick prompts */}
      <div className="shrink-0 flex gap-2 overflow-x-auto px-5 pb-2 pt-1 [scrollbar-width:none]">
        {QUICK_PROMPTS.map((p) => (
          <button
            key={p}
            onClick={() => sendPrompt(p)}
            className="shrink-0 rounded-full border border-border bg-glass px-3.5 py-2 text-[12px] font-semibold text-text-dim whitespace-nowrap"
          >
            {p}
          </button>
        ))}
      </div>

      {/* Input */}
      <form className="shrink-0 px-5 pb-[110px] pt-2" onSubmit={submit}>
        <div className="flex items-center gap-2.5 rounded-full border border-border bg-glass py-1.5 pl-[18px] pr-1.5">
          <input
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder="Pregúntale a Titan..."
            className="flex-1 bg-transparent py-2 text-[14px] text-text placeholder:text-text-dimmer outline-none"
          />
          <button
            type="submit"
            disabled={!text.trim()}
            className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-accent text-[15px] font-extrabold text-black disabled:opacity-40"
          >
            ↑
          </button>
        </div>
      </form>

      <TabBar />
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { useTitanStore } from "@/lib/store";
import { useRequireOnboarding } from "@/lib/useRequireOnboarding";
import { ScreenHeader } from "@/components/ScreenHeader";
import { TabBar } from "@/components/TabBar";
import { GlassCard } from "@/components/ui/GlassCard";

type SocialTab = "feed" | "amigos" | "duelos";

export default function SocialPage() {
  const ready = useRequireOnboarding();
  const { friends, feed } = useTitanStore();
  const [tab, setTab] = useState<SocialTab>("feed");

  if (!ready) return null;

  const tabs: { id: SocialTab; label: string; icon: string }[] = [
    { id: "feed", label: "Actividad", icon: "📡" },
    { id: "amigos", label: "Amigos", icon: "👥" },
    { id: "duelos", label: "Duelos", icon: "⚔️" },
  ];

  return (
    <div className="flex min-h-dvh flex-col gap-4 px-4 pb-[110px]">
      <ScreenHeader title="Social" subtitle="Tu comunidad de entrenamiento" />

      {/* Tabs */}
      <div className="flex gap-2">
        {tabs.map((t) => (
          <button
            key={t.id}
            onClick={() => setTab(t.id)}
            className={`flex-1 rounded-full py-2.5 text-[12px] font-bold transition-all ${
              tab === t.id
                ? "bg-accent text-black"
                : "border border-border bg-glass text-text-dim"
            }`}
          >
            {t.icon} {t.label}
          </button>
        ))}
      </div>

      {/* Feed */}
      {tab === "feed" && (
        <div className="flex flex-col gap-2">
          {feed.map((item, i) => (
            <motion.div
              key={item.id}
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.05 }}
            >
              <GlassCard className="flex items-start gap-3 p-3.5">
                <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-border bg-glass text-sm font-bold">
                  {item.userName[0]}
                </div>
                <div className="min-w-0 flex-1">
                  <div className="text-[13.5px]">
                    <span className="font-semibold">{item.userName}</span>{" "}
                    <span className="text-text-dim">{item.action}</span>
                  </div>
                  <div className="mt-0.5 text-[11px] text-text-dimmer">
                    {item.timestamp}
                  </div>
                </div>
              </GlassCard>
            </motion.div>
          ))}
        </div>
      )}

      {/* Amigos */}
      {tab === "amigos" && (
        <div className="flex flex-col gap-3">
          {/* Buscar */}
          <div className="relative">
            <input
              placeholder="Buscar usuario..."
              className="w-full rounded-full border border-border bg-glass px-5 py-3 text-[14px] text-text placeholder:text-text-dimmer outline-none focus:border-accent"
            />
          </div>

          {/* Lista */}
          {friends.map((f, i) => (
            <motion.div
              key={f.id}
              initial={{ opacity: 0, x: -8 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: i * 0.05 }}
            >
              <GlassCard className="flex items-center gap-3 p-3.5">
                <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full border border-border bg-glass text-[14px] font-bold">
                  {f.name[0]}
                </div>
                <div className="min-w-0 flex-1">
                  <div className="text-[14px] font-semibold">{f.name}</div>
                  <div className="text-[11px] text-text-dim">
                    Nv. {f.level} · 🔥 {f.streak} días · {f.commitmentIndex}% índice
                  </div>
                </div>
                <button className="rounded-full border border-border-strong px-3 py-1.5 text-[11px] font-semibold text-text-dim">
                  Ver
                </button>
              </GlassCard>
            </motion.div>
          ))}

          {/* Invitar */}
          <GlassCard className="flex flex-col items-center gap-2 p-5 text-center">
            <div className="text-[32px]">👥</div>
            <div className="text-[14px] font-bold">Invita a tus amigos</div>
            <div className="text-[12px] text-text-dim">
              Compite con ellos y motívate mutuamente
            </div>
            <div className="mt-2 flex gap-2">
              <button className="rounded-full bg-accent px-5 py-2.5 text-[12px] font-bold text-black">
                Invitar por enlace
              </button>
              <button className="rounded-full border border-border-strong px-4 py-2.5 text-[12px] font-semibold">
                QR
              </button>
            </div>
          </GlassCard>
        </div>
      )}

      {/* Duelos */}
      {tab === "duelos" && (
        <div className="flex flex-col gap-3">
          {/* Info */}
          <GlassCard className="p-4">
            <div className="text-[13px] font-bold">⚔️ Duelos de fin de semana</div>
            <div className="mt-1 text-[12px] text-text-dim">
              Los duelos están disponibles únicamente sábado y domingo. Elige un rival entre tus amigos y compite en tiempo real.
            </div>
          </GlassCard>

          {/* Tipos de duelo */}
          <div className="text-[12px] font-bold text-text-dim px-1">Tipos disponibles</div>
          <div className="grid grid-cols-2 gap-2">
            {[
              "Dominadas", "Flexiones", "Sentadillas", "Abdominales",
              "Burpees", "5 km", "10 km", "Pasos",
              "Calorías", "Tiempo entreno", "Distancia ciclismo", "Volumen total",
            ].map((type) => (
              <GlassCard key={type} className="flex items-center gap-2 p-3">
                <div className="text-[13px] font-semibold">{type}</div>
              </GlassCard>
            ))}
          </div>

          {/* CTA */}
          <GlassCard className="flex flex-col items-center gap-2 p-5 text-center">
            <div className="text-[32px]">🏆</div>
            <div className="text-[14px] font-bold">Lanza un duelo</div>
            <div className="text-[12px] text-text-dim">
              Disponible el próximo fin de semana
            </div>
            <button
              disabled
              className="mt-2 rounded-full bg-accent/40 px-6 py-3 text-[13px] font-bold text-black/60 cursor-not-allowed"
            >
              Disponible el sábado
            </button>
          </GlassCard>
        </div>
      )}

      <TabBar />
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { useTitanStore } from "@/lib/store";
import { useRequireOnboarding } from "@/lib/useRequireOnboarding";
import { ScreenHeader } from "@/components/ScreenHeader";
import { TabBar } from "@/components/TabBar";
import { PillButton } from "@/components/ui/PillButton";
import { GlassCard } from "@/components/ui/GlassCard";

export default function CompraPage() {
  const ready = useRequireOnboarding();
  const shoppingList = useTitanStore((s) => s.shoppingList);
  const toggleShoppingItem = useTitanStore((s) => s.toggleShoppingItem);
  const resetShoppingList = useTitanStore((s) => s.resetShoppingList);
  const profile = useTitanStore((s) => s.profile);

  const { grouped, pct, allDone } = useMemo(() => {
    const grouped: Record<string, typeof shoppingList> = {};
    shoppingList.forEach((item) => {
      grouped[item.category] = grouped[item.category] || [];
      grouped[item.category].push(item);
    });
    const doneCount = shoppingList.filter((i) => i.checked).length;
    const pct = Math.round((doneCount / shoppingList.length) * 100);
    return { grouped, pct, allDone: doneCount === shoppingList.length };
  }, [shoppingList]);

  if (!ready) return null;

  const market = profile.supermarket ?? "tu supermercado";

  return (
    <div className="flex min-h-dvh flex-col gap-4 px-4 pb-[110px]">
      <ScreenHeader
        title="Lista de la compra"
        subtitle={`Semana actual · ${market}`}
      />

      {/* Progress sticky */}
      <div className="sticky top-0 z-10 -mx-4 bg-bg/90 px-4 pb-3 pt-1 backdrop-blur-md">
        <div className="flex items-center justify-between text-[12px] font-semibold text-text-dim">
          <span>{pct}% completado</span>
          <button
            onClick={resetShoppingList}
            className="text-text-dimmer underline underline-offset-2"
          >
            Reiniciar
          </button>
        </div>
        <div className="mt-2 h-[6px] overflow-hidden rounded-full bg-white/8">
          <div
            className="h-full rounded-full bg-accent transition-all duration-500"
            style={{ width: `${pct}%` }}
          />
        </div>
      </div>

      {allDone && (
        <div className="rounded-[20px] border border-accent bg-accent-dim p-4 text-center text-[13.5px] font-semibold text-accent">
          🛒 Compra completada
        </div>
      )}

      <div className="flex flex-col gap-5">
        {Object.entries(grouped).map(([category, items]) => (
          <div key={category}>
            <div className="mb-2 px-1 text-[12px] font-bold text-text-dim">
              {category}
            </div>
            <div className="flex flex-col gap-2">
              {items.map((item) => (
                <button
                  key={item.id}
                  onClick={() => toggleShoppingItem(item.id)}
                  className="flex w-full items-center gap-3 rounded-[14px] border border-border bg-glass px-4 py-3.5 text-left transition-all active:scale-[0.98]"
                >
                  <span
                    className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-[7px] border text-[13px] font-bold transition-all ${
                      item.checked
                        ? "border-accent bg-accent text-black"
                        : "border-border-strong text-transparent"
                    }`}
                  >
                    ✓
                  </span>
                  <span
                    className={`text-[14px] transition-all ${
                      item.checked ? "text-text-dimmer line-through" : "text-text"
                    }`}
                  >
                    {item.name}
                  </span>
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>

      <PillButton
        variant="secondary"
        className="mt-1 w-full py-3 text-center"
        onClick={() => alert("Titan buscará sustituciones equivalentes automáticamente.")}
      >
        No encuentro un producto
      </PillButton>

      <TabBar />
    </div>
  );
}

