      <GlassCard className="p-4">
        <div className="mb-3 flex items-center justify-between">
          <div>
            <div className="tabular-nums text-[26px] font-extrabold">{last} kg</div>
            <div className="mt-0.5 text-[12px] text-text-dim">Peso actual</div>
          </div>
          <div
